import{_ as e,c as r,o as t,a2 as i}from"./chunks/framework.CIiVzG-O.js";const f=JSON.parse('{"title":"常见问题","description":"关于价格、隐私、支持机型、文件夹、界面语言与恢复购买的解答。","frontmatter":{"title":"常见问题","description":"关于价格、隐私、支持机型、文件夹、界面语言与恢复购买的解答。"},"headers":[],"relativePath":"zh-CN/guide/faq.md","filePath":"zh-CN/guide/faq.md","lastUpdated":1793948370000}'),h={name:"zh-CN/guide/faq.md"};function o(l,a,d,n,s,c){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h3 id="qdiff-免费吗" tabindex="-1">qDiff 免费吗？ <a class="header-anchor" href="#qdiff-免费吗" aria-label="Permalink to &quot;qDiff 免费吗？&quot;">​</a></h3><p>免费。所有比较、查看和导出功能，不付费也能用。免费版只在标签条上多一个 「未授权」小标记。一次性购买会去掉它，并包含以后新增的高级功能。没有订阅， 也没有广告。</p><h3 id="购买之后会解锁新功能吗" tabindex="-1">购买之后会解锁新功能吗？ <a class="header-anchor" href="#购买之后会解锁新功能吗" aria-label="Permalink to &quot;购买之后会解锁新功能吗？&quot;">​</a></h3><p>不会 —— 功能本来就全部可用。购买只是去掉那个小标记。以后如果增加高级能力， 也会算在同一次购买里，不会再卖第二个商品。</p><h3 id="换电脑后怎么恢复购买" tabindex="-1">换电脑后怎么恢复购买？ <a class="header-anchor" href="#换电脑后怎么恢复购买" aria-label="Permalink to &quot;换电脑后怎么恢复购买？&quot;">​</a></h3><p>打开「设置 → 高级功能」，点「恢复购买」。购买记录与 Apple ID 绑定，在你的 其他 Mac 上同样有效。</p><h3 id="支持哪些-mac" tabindex="-1">支持哪些 Mac？ <a class="header-anchor" href="#支持哪些-mac" aria-label="Permalink to &quot;支持哪些 Mac？&quot;">​</a></h3><p>macOS 12 或更新版本，Apple 芯片与 Intel 机型都可以，详见 <a href="./download.html#system-requirements">系统要求</a>。</p><h3 id="需要账号或联网吗" tabindex="-1">需要账号或联网吗？ <a class="header-anchor" href="#需要账号或联网吗" aria-label="Permalink to &quot;需要账号或联网吗？&quot;">​</a></h3><p>不需要。qDiff 离线可用，不用登录，也没有后台服务。它只打开你选择的文件和 文件夹。</p><h3 id="能比较整个文件夹和压缩包吗" tabindex="-1">能比较整个文件夹和压缩包吗？ <a class="header-anchor" href="#能比较整个文件夹和压缩包吗" aria-label="Permalink to &quot;能比较整个文件夹和压缩包吗？&quot;">​</a></h3><p>能。文件夹以树形展开，可按状态筛选、直接复制和同步；.zip / .tar 不用解压， 也能当文件夹来比。</p><h3 id="图片和不是文本的文件呢" tabindex="-1">图片和不是文本的文件呢？ <a class="header-anchor" href="#图片和不是文本的文件呢" aria-label="Permalink to &quot;图片和不是文本的文件呢？&quot;">​</a></h3><p>图片可以并排看，也可以叠加看差异；不是纯文本的文件，还能细到最小的差别。 见<a href="./more.html">更多比较方式</a>。</p><h3 id="你们会上传或分析我的文件吗" tabindex="-1">你们会上传或分析我的文件吗？ <a class="header-anchor" href="#你们会上传或分析我的文件吗" aria-label="Permalink to &quot;你们会上传或分析我的文件吗？&quot;">​</a></h3><p>不会。不收集、不追踪、不上传，完整说明见<a href="./../privacy/">隐私政策</a>。</p><h3 id="界面有中文吗" tabindex="-1">界面有中文吗？ <a class="header-anchor" href="#界面有中文吗" aria-label="Permalink to &quot;界面有中文吗？&quot;">​</a></h3><p>有简体中文、繁体中文、英文等多种语言，并支持浅色与深色外观。</p><h3 id="用的时候遇到问题怎么办" tabindex="-1">用的时候遇到问题怎么办？ <a class="header-anchor" href="#用的时候遇到问题怎么办" aria-label="Permalink to &quot;用的时候遇到问题怎么办？&quot;">​</a></h3><p><a href="./support.html">联系我们</a>，附上 macOS 版本和一句症状描述就好；有截图会更快。</p>',21)])])}const q=e(h,[["render",o]]);export{f as __pageData,q as default};
